using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app", Name = "App Configuration",
        MimeType = "application/json")]
    [Description("Returns the current application configuration as JSON.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            Environment = "Production",
            Version = "1.0.0",
            Features = new { DarkMode = true, BetaAccess = false },
            MaxRetries = 3,
            TimeoutSeconds = 30
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://endpoints", Name = "API Endpoints",
        MimeType = "application/json")]
    [Description("Returns the list of available API endpoints and their status.")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Path = "/api/users", Method = "GET", Status = "active" },
            new { Path = "/api/orders", Method = "POST", Status = "active" },
            new { Path = "/api/reports", Method = "GET", Status = "maintenance" }
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Echoes back the provided message, useful for connectivity testing.")]
    public static string Echo([Description("The message to echo back")] string message)
    {
        return $"Echo: {message}";
    }

    [McpServerTool, Description("Returns the current server time in UTC.")]
    public static string GetServerTime()
    {
        return DateTime.UtcNow.ToString("o");
    }
}

